import React, { useState } from 'react'
import s from './HW11.module.css'
import s2 from '../../s1-main/App.module.css'
import {restoreState, saveState} from '../hw06/localStorage/localStorage'
import SuperRange from './common/c7-SuperRange/SuperRange'

/*
* 1 - передать значения в оба слайдера
* 2 - дописать типы и логику функции change
* 3 - сделать стили в соответствии с дизайном
* */

function HW11() {
    // for autotests // не менять // можно подсунуть в локалСторэдж нужные числа, чтоб увидеть как они отображаются
    const [value1, setValue1] = useState(restoreState<number>('hw11-value1', 0))
    const [value2, setValue2] = useState(restoreState<number>('hw11-value2', 100))

    const change = <T,>(event: Event, value: T) => {
        // пишет студент // если пришёл массив - сохранить значения в оба useState, иначе в первый
        if (Array.isArray(value)) {
            const [newValue1, newValue2] = value as number[]
            setValue1(newValue1)
            setValue2(newValue2)
            saveState<number>('hw11-value1', newValue1)
            saveState<number>('hw11-value2', newValue2)
        } else if (typeof value === 'number') {
            setValue1(value)
            saveState<number>('hw11-value1', value)
        }
    }

    return (
        <div id={'hw11'}>
            <hr/>
            <div className={s2.hwTitle}>Hometask #11</div>
            <hr/>
            <div className={s2.hw}>
                <div className={s.container}>
                    <div className={s.wrapper}>
                        <span id={'hw11-value'} className={s.number}>{value1}</span>
                        <SuperRange
                            id={'hw11-single-slider'}
                            style={{display: "inline-block"}}
                            onChange={change}
                            value={value1}
                        />
                    </div>
                    <div className={s.wrapper}>
                        <span id={'hw11-value-1'} className={s.number}>{value1}</span>
                        <SuperRange
                            id={'hw11-double-slider'}
                            style={{display: "inline-block"}}
                            onChange={change}
                            value={[value1, value2]}
                        />
                        <span id={'hw11-value-2'} className={s.number}>{value2}</span>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default HW11
